            print("❌ 混合ANOVA需要 --subject, --within, --between, --dv 参数")
            print("   示例: python exp_analysis.py --mixed-anova data.csv --subject id --within time --between group --dv Y")
            sys.exit(EXIT_CONFIG_ERROR)
